mapper.select:
SELECT  COUNT(grid_id) as gridNum,IFNULL(SUM(IF(point_status ='1',1,0)),0) as gridMarkNum,IFNULL(SUM(IF(point_status ='0' OR point_status IS NULL,1,0)),0) as gridNoMarkNum
FROM bm_grid dataTable

    and dataTable.delete_flag = 0
    ${dataScope}

        and dataTable.grid_id = #{gridId}


        and dataTable.grid_id in

            #{item}

SELECT  grid_level as gridLevel,point_status as pointStatus
FROM bm_grid dataTable

    and dataTable.delete_flag = 0
    ${dataScope}

        and dataTable.grid_id = #{gridId}

SELECT dataTable.login_name as loginName,dataTable.keeper_type as keeperType,IFNULL(dataTable.keeper_gender,'') as keeperGender,IFNULL(TIMESTAMPDIFF(YEAR, STR_TO_DATE(SUBSTRING(dataTable.keeper_id_card_number, 7, 8), '%Y%m%d'), CURDATE()),'') as age,CAST(b.grid_id AS CHAR) as gridId,IFNULL(b.grid_name,'') as gridName FROM bm_gridkeeper dataTable LEFT JOIN bm_grid_keeper_ref r ON dataTable.keeper_id = r.keeper_id and r.delete_flag = 0 LEFT JOIN bm_grid b ON r.grid_id = b.grid_id and b.delete_flag = 0
and dataTable.delete_flag = 0 ${dataScope}
and dataTable.keeper_id = #{keeperId}

SELECT  COUNT(keeper_id) as gridKeeperNum,IFNULL(SUM(IF(keeper_type =1,1,0)),0) as gridKeeperOneNum,IFNULL(SUM(IF(keeper_type =2,1,0)),0) as gridKeeperTwoNum
FROM bm_gridkeeper dataTable

    and dataTable.delete_flag = 0 and	dataTable.`status` = 0
    ${dataScope}

        and dataTable.keeper_id in (select r.keeper_id from bm_grid_keeper_ref r where r.delete_flag = '0' and r.grid_id = #{gridId} )


        and dataTable.keeper_id in (select r.keeper_id from bm_grid_keeper_ref r where r.delete_flag = '0' and r.grid_id in

            #{item}

        )

SELECT a.inspectionTaskNum, a.taskCompletedNum, a.taskIncompleteNum, IF(a.inspectionTaskNum = 0 OR a.inspectionTaskNum IS NULL,NULL,IFNULL(ROUND((a.taskCompletedNum /a.inspectionTaskNum) *100),0)) AS taskCompletedRate FROM (SELECT IFNULL( SUM( IF ( dataTable.task_status = '1' OR dataTable.task_status = '2' , 1, 0 )), 0 ) as inspectionTaskNum, IFNULL(SUM(IF(task_status ='1',1,0)),0) as taskCompletedNum, IFNULL(SUM(IF(task_status ='2',1,0)),0) as taskIncompleteNum FROM bm_inspection_task dataTable
and dataTable.delete_flag = 0 and dataTable.send_flag = 1 ${dataScope}
AND dataTable.grid_id LIKE concat('%',#{gridId},'%')
and dataTable.grid_id in
#{item}
AND dataTable.create_time >= #{queryStartTime} AND dataTable.create_time <= #{queryEndTime}
) a

SELECT IFNULL(SUM(IF(b.noNormalCount = '0' AND b.normalCount !='0',1,0)),0) as normalCount,IFNULL(SUM(IF(b.noNormalCount != '0'AND b.workDay !='0',1,0)),0) as noNormalCount,IFNULL(SUM(b.workDay),0) as workDay,IFNULL(SUM(b.clockInNum),0) as lockInNum, IF(SUM(b.workDay) = 0 OR SUM(b.workDay) is NULL,NULL,IFNULL(ROUND((SUM(b.clockInNum)/SUM(b.workDay)) *100),0)) AS attendanceRate FROM( SELECT SUM(IF(sign_in_status ='1' AND sign_out_status ='4' ,1,0)) as normalCount, SUM(IF(sign_in_status !='1' OR sign_out_status !='4' OR sign_in_status IS NULL OR sign_out_status IS NULL,1,0)) as noNormalCount, COUNT(s.attendance_id) as workDay, SUM(IF(sign_in_status ='1' OR sign_in_status = '2' OR sign_out_status ='4' OR sign_out_status = '5',1,0)) AS clockInNum FROM bm_gridkeeper dataTable LEFT JOIN bm_grid_keeper_ref b ON dataTable.keeper_id = b.keeper_id and b.delete_flag = 0 LEFT JOIN bm_attendance_line s ON s.grid_id = b.grid_id and s.keeper_id = b.keeper_id and s.delete_flag = 0
AND s.attendance_date >= DATE_FORMAT(#{queryStartTime}, '%Y-%m-%d') AND s.attendance_date <= DATE_FORMAT(#{queryEndTime}, '%Y-%m-%d')
and dataTable.delete_flag=0 AND dataTable.status=0 ${dataScope}
AND s.grid_id = #{gridId}
and s.grid_id in
#{item}
GROUP BY s.keeper_id )b

SELECT COUNT(grid_id) as gridNum,grid_level as gridLevel FROM bm_grid dataTable
and dataTable.delete_flag = 0 ${dataScope}
and dataTable.grid_id = #{gridId}
GROUP BY grid_level ORDER BY CAST(grid_level AS UNSIGNED),COUNT(grid_id) DESC

SELECT IFNULL(ROUND((b.gridKeeperManNum/b.gridKeeperNum) *100),0) AS manRate,IFNULL(ROUND((b.gridKeeperWomanNum/b.gridKeeperNum) *100),0) AS womanRate,IFNULL(ROUND((b.unknownNum/b.gridKeeperNum) *100),0) AS unknownRate, IFNULL(gridKeeperNum,0) as gridKeeperNum ,IFNULL(gridKeeperManNum,0) as gridKeeperManNum,IFNULL(gridKeeperWomanNum,0) as gridKeeperWomanNum,IFNULL(unknownNum,0) as unknownNum FROM( SELECT COUNT(keeper_id) as gridKeeperNum,SUM(IF(keeper_gender = '0',1,0)) as gridKeeperManNum,SUM(IF(keeper_gender = '1',1,0)) as gridKeeperWomanNum, SUM(IF(keeper_gender IS NULL OR keeper_gender ='',1,0)) as unknownNum FROM bm_gridkeeper dataTable
and dataTable.delete_flag = 0 and dataTable.`status` = 0 ${dataScope}
and dataTable.keeper_id in (select r.keeper_id from bm_grid_keeper_ref r where r.delete_flag = '0' and r.grid_id = #{gridId} )
) b

SELECT CAST(b.gridId AS CHAR) as gridId,b.gridName,b.gridLevel,SUM(b.clockInNum) as clockInNum,SUM(b.workDay) as workDay ,IF(SUM(b.workDay) = 0 OR SUM(b.workDay) IS NULL,NULL,IFNULL(ROUND((SUM(b.clockInNum)/SUM(b.workDay)) *100),0)) AS attendanceRate, IFNULL((SUM(b.clockInNum)/SUM(b.workDay) *100),0) AS attendanceRates FROM( SELECT dataTable.grid_id AS gridId, g.keeper_id as keeperId, dataTable.grid_name AS gridName, dataTable.grid_level AS gridLevel, COUNT(g.attendance_id) as workDay, SUM(IF(g.sign_in_status ='1' OR g.sign_in_status = '2' OR g.sign_out_status ='4' OR g.sign_out_status = '5',1,0)) AS clockInNum FROM bm_grid dataTable LEFT JOIN bm_grid_keeper_ref r ON dataTable.grid_id = r.grid_id and r.delete_flag = 0 LEFT JOIN bm_gridkeeper s ON s.keeper_id = r.keeper_id and s.delete_flag=0 AND s.status=0 LEFT JOIN bm_attendance_line g ON s.keeper_id = g.keeper_id and g.grid_id = r.grid_id and g.delete_flag = 0 and g.keeper_id is not null
AND g.attendance_date >= DATE_FORMAT(#{queryStartTime}, '%Y-%m-%d') AND g.attendance_date <= DATE_FORMAT(#{queryEndTime}, '%Y-%m-%d')
and dataTable.delete_flag = 0
AND dataTable.grid_id = #{gridId}
${dataScope}
GROUP BY dataTable.grid_id,g.keeper_id )b GROUP BY b.gridId ORDER BY ISNULL(attendanceRate),attendanceRates DESC,CAST(b.gridLevel AS UNSIGNED),CONVERT(b.gridName USING GBK)

SELECT CAST(b.keeper_id AS CHAR) as keeperId,b.keeperName,IFNULL(b.workDay,0) as workDay,IFNULL(b.clockInNum,0) as clockInNum, IF(b.workDay = 0 OR b.workDay IS NULL ,NULL,IFNULL(ROUND((b.clockInNum/b.workDay) *100),0)) AS attendanceRate, IFNULL((b.clockInNum/b.workDay *100),0) AS attendanceRates FROM( SELECT COUNT(g.attendance_id) as workDay,dataTable.keeper_id,dataTable.keeper_name as keeperName, SUM(IF(sign_in_status ='1' OR sign_in_status = '2' OR sign_out_status ='4' OR sign_out_status = '5',1,0)) AS clockInNum FROM bm_gridkeeper dataTable LEFT JOIN bm_grid_keeper_ref b ON dataTable.keeper_id = b.keeper_id and b.delete_flag = 0 LEFT JOIN bm_attendance_line g ON b.grid_id = g.grid_id and b.keeper_id = g.keeper_id and g.delete_flag = 0
AND g.attendance_date >= DATE_FORMAT(#{queryStartTime}, '%Y-%m-%d') AND g.attendance_date <= DATE_FORMAT(#{queryEndTime}, '%Y-%m-%d')
AND dataTable.delete_flag = 0 AND dataTable.`status` = 0
and dataTable.keeper_type = #{keeperType}
${dataScope}
AND g.grid_id = #{gridId}
GROUP BY dataTable.keeper_id )b ORDER BY ISNULL(attendanceRate),attendanceRates DESC,CONVERT(b.keeperName USING GBK)

SELECT CAST(b.keeper_id AS CHAR) as keeperId,b.keeperName,IFNULL(b.workDay,0) as workDay,IFNULL(b.clockInNum,0) as clockInNum, IF(b.workDay = 0 OR b.workDay IS NULL ,NULL,IFNULL(ROUND((b.clockInNum/b.workDay) *100),0)) AS attendanceRate, IFNULL((b.clockInNum/b.workDay *100),0) AS attendanceRates FROM( SELECT COUNT(g.attendance_id) as workDay,dataTable.keeper_id,dataTable.keeper_name as keeperName, SUM(IF(sign_in_status ='1' OR sign_in_status = '2' OR sign_out_status ='4' OR sign_out_status = '5',1,0)) AS clockInNum FROM bm_gridkeeper dataTable LEFT JOIN bm_grid_keeper_ref b ON dataTable.keeper_id = b.keeper_id and b.delete_flag = 0 LEFT JOIN bm_attendance_line g ON b.grid_id = g.grid_id and b.keeper_id = g.keeper_id and g.delete_flag = 0
AND g.attendance_date >= DATE_FORMAT(#{queryStartTime}, '%Y-%m-%d') AND g.attendance_date <= DATE_FORMAT(#{queryEndTime}, '%Y-%m-%d')
AND dataTable.delete_flag = 0 AND dataTable.`status` = 0 and dataTable.keeper_type = '2' ${dataScope}
AND g.grid_id = #{gridId}
GROUP BY dataTable.keeper_id )b ORDER BY ISNULL(attendanceRate),attendanceRates DESC,CONVERT(b.keeperName USING GBK)

SELECT CAST(a.keeper_id AS CHAR) as keeper_id,GROUP_CONCAT(b.grid_name) AS grid_name,GROUP_CONCAT(b.grid_level) AS grid_level FROM bm_grid_keeper_ref a LEFT JOIN bm_grid b ON a.grid_id = b.grid_id WHERE a.delete_flag = 0 and a.keeper_id IN
#{item}
GROUP BY a.keeper_id

SELECT CAST(dataTable.grid_id AS CHAR) as gridId,dataTable.grid_name as gridName,IFNULL( SUM( IF ( g.task_status = '1' OR g.task_status = '2' , 1, 0 )), 0 ) as inspectionTaskNum, IFNULL(SUM(IF(g.task_status ='1',1,0)),0) as taskCompletedNum, IFNULL(SUM(IF(g.task_status ='2',1,0)),0) as taskIncompleteNum FROM bm_grid dataTable LEFT JOIN bm_inspection_task g ON dataTable.grid_id = g.grid_id and g.delete_flag = 0 and g.send_flag = 1
AND g.create_time >= #{queryStartTime} AND g.create_time <= #{queryEndTime}
and dataTable.delete_flag = 0 ${dataScope}
AND g.grid_id LIKE concat('%',#{gridId},'%')
GROUP BY dataTable.grid_id ORDER BY inspectionTaskNum DESC,CONVERT(dataTable.grid_name USING GBK)

SELECT a.gridId, a.gridName, a.gridLevel, a.inspectionTaskNum, a.taskCompletedNum, IF(a.inspectionTaskNum = 0 OR a.inspectionTaskNum IS NULL,NULL,IFNULL(ROUND((a.taskCompletedNum /a.inspectionTaskNum) *100),0)) AS taskCompletedRate, IFNULL((IFNULL(a.taskCompletedNum,0)/a.inspectionTaskNum) *100, 0) AS taskCompletedRates FROM ( SELECT CAST( dataTable.grid_id AS CHAR ) AS gridId, dataTable.grid_name AS gridName, dataTable.grid_level AS gridLevel, IFNULL( SUM( IF ( g.task_status = '1' OR g.task_status = '2', 1, 0 )), 0 ) AS inspectionTaskNum, IFNULL( SUM( IF ( g.task_status = '1', 1, 0 )), 0 ) AS taskCompletedNum FROM bm_grid dataTable LEFT JOIN bm_inspection_task g ON dataTable.grid_id = g.grid_id AND g.delete_flag = 0 AND g.send_flag = 1
AND g.create_time >= #{queryStartTime} AND g.create_time <= #{queryEndTime}
and dataTable.delete_flag = 0 ${dataScope}
AND g.grid_id LIKE concat('%',#{gridId},'%')
GROUP BY dataTable.grid_id ) a ORDER BY ISNULL( taskCompletedRate ), taskCompletedRates DESC, CAST(a.gridLevel AS UNSIGNED), CONVERT (a.gridName USING GBK)

SELECT CONCAT(a.grid_id, '') AS gridId, a.grid_name AS gridName, CONCAT(a.keeperId, '') AS keeperId, a.keeperNum, IFNULL( CASE WHEN a.keeper_type = '1' THEN '网格长' ELSE '网格员' END, '网格员' ) AS keeperType, IFNULL( a.keeper_type, '2' ) AS keeper_type, a.inspectionTaskNum, a.taskCompletedNum, a.taskIncompleteNum, IFNULL( ROUND(( IFNULL( a.taskCompletedNum, 0 )/ a.inspectionTaskNum ) * 100, 2 ), 0 ) AS taskCompletedRate FROM ( SELECT dataTable.grid_id, dataTable.grid_name, r.keeper_type, r.keeper_id AS keeperId, r.keeper_name AS keeperName, COUNT( r.keeper_id ) AS keeperNum, IFNULL( SUM( IF ( (t.task_status = '1' and t.feedback_keeper_id = r.keeper_id) OR t.task_status = '2' , 1, 0 )), 0 ) AS inspectionTaskNum, IFNULL( SUM( IF ( t.task_status = '1' and t.feedback_keeper_id =r.keeper_id , 1, 0 )), 0 ) AS taskCompletedNum, IFNULL( SUM( IF ( t.task_status = '2', 1, 0 )), 0 ) AS taskIncompleteNum FROM bm_grid dataTable LEFT JOIN bm_inspection_task t ON dataTable.grid_id = t.grid_id AND t.send_flag = 1 AND t.delete_flag = 0
AND t.create_time >= #{queryStartTime} AND t.create_time <= #{queryEndTime}
LEFT JOIN bm_gridkeeper r ON FIND_IN_SET( r.keeper_id, t.keeper_id ) AND r.delete_flag = 0
AND dataTable.delete_flag = 0 ${dataScope}
GROUP BY dataTable.grid_id, r.keeper_type ) a ORDER BY a.grid_id DESC

SELECT a.inspectionTaskNum,a.inspectionTaskNumPc,a.inspectionTaskNumApp, IFNULL(ROUND((IFNULL(a.inspectionTaskNumPc,0)/a.inspectionTaskNum) *100),0) AS pcRate, IFNULL(ROUND((IFNULL(a.inspectionTaskNumApp,0)/a.inspectionTaskNum) *100),0) AS appRate FROM( SELECT IFNULL( SUM( IF ( dataTable.task_status = '1' OR dataTable.task_status = '2' , 1, 0 )), 0 ) as inspectionTaskNum, IFNULL(SUM(IF(dataTable.feedback_end ='1',1,0)),0) as inspectionTaskNumPc, IFNULL(SUM(IF(dataTable.feedback_end ='2',1,0)),0) as inspectionTaskNumApp, IFNULL(ROUND((IFNULL(SUM(IF(dataTable.feedback_end ='1',1,0)),0)/COUNT(dataTable.task_id)) *100),0) AS pcRate, IFNULL(ROUND((IFNULL(SUM(IF(dataTable.feedback_end ='2',1,0)),0)/COUNT(dataTable.task_id)) *100),0) AS appRate FROM bm_inspection_task dataTable
and dataTable.delete_flag = 0 and dataTable.send_flag = 1 AND dataTable.task_status = '1' ${dataScope}
AND dataTable.grid_id LIKE concat('%',#{gridId},'%')
AND dataTable.inspection_time >= #{queryStartTime} AND dataTable.inspection_time <= #{queryEndTime}
)a WHERE a.inspectionTaskNum > 0

SELECT t1.label,IFNULL(t2.inspectionTaskBackNum,0) AS inspectionTaskBackNum FROM ( SELECT 0 AS `hour`,'0:00-1:00' AS label UNION SELECT 1 AS `hour`,'1:00-2:00' AS label UNION SELECT 2 AS `hour`,'2:00-3:00' AS label UNION SELECT 3 AS `hour`,'3:00-4:00' AS label UNION SELECT 4 AS `hour`,'4:00-5:00' AS label UNION SELECT 5 AS `hour`,'5:00-6:00' AS label UNION SELECT 6 AS `hour`,'6:00-7:00' AS label UNION SELECT 7 AS `hour`,'7:00-8:00' AS label UNION SELECT 8 AS `hour`,'8:00-9:00' AS label UNION SELECT 9 AS `hour`,'9:00-10:00' AS label UNION SELECT 10 AS `hour`,'10:00-11:00' AS label UNION SELECT 11 AS `hour`,'11:00-12:00' AS label UNION SELECT 12 AS `hour`,'12:00-13:00' AS label UNION SELECT 13 AS `hour`,'13:00-14:00' AS label UNION SELECT 14 AS `hour`,'14:00-15:00' AS label UNION SELECT 15 AS `hour`,'15:00-16:00' AS label UNION SELECT 16 AS `hour`,'16:00-17:00' AS label UNION SELECT 17 AS `hour`,'17:00-18:00' AS label UNION SELECT 18 AS `hour`,'18:00-19:00' AS label UNION SELECT 19 AS `hour`,'19:00-20:00' AS label UNION SELECT 20 AS `hour`,'20:00-21:00' AS label UNION SELECT 21 AS `hour`,'21:00-22:00' AS label UNION SELECT 22 AS `hour`,'22:00-23:00' AS label UNION SELECT 23 AS `hour`,'23:00-24:00' AS label) t1 LEFT JOIN (SELECT HOUR(inspection_time) as hour,IFNULL(SUM(IF(dataTable.feedback_end ='1' OR dataTable.feedback_end ='2',1,0)),0) as inspectionTaskBackNum FROM bm_inspection_task dataTable
and dataTable.delete_flag = 0 and dataTable.send_flag = 1 AND dataTable.task_status = '1' ${dataScope}
AND dataTable.grid_id LIKE concat('%',#{gridId},'%')
AND dataTable.inspection_time >= #{queryStartTime} AND dataTable.inspection_time <= #{queryEndTime}
GROUP BY HOUR(dataTable.inspection_time) )t2 ON t1.hour = t2.hour ORDER BY t1.`hour`

SELECT t1.label,IFNULL(t2.inspectionTaskBackNum,0) AS inspectionTaskBackNum FROM ( SELECT 0 AS `hour`,'0:00-1:00' AS label UNION SELECT 1 AS `hour`,'1:00-2:00' AS label UNION SELECT 2 AS `hour`,'2:00-3:00' AS label UNION SELECT 3 AS `hour`,'3:00-4:00' AS label UNION SELECT 4 AS `hour`,'4:00-5:00' AS label UNION SELECT 5 AS `hour`,'5:00-6:00' AS label UNION SELECT 6 AS `hour`,'6:00-7:00' AS label UNION SELECT 7 AS `hour`,'7:00-8:00' AS label UNION SELECT 8 AS `hour`,'8:00-9:00' AS label UNION SELECT 9 AS `hour`,'9:00-10:00' AS label UNION SELECT 10 AS `hour`,'10:00-11:00' AS label UNION SELECT 11 AS `hour`,'11:00-12:00' AS label UNION SELECT 12 AS `hour`,'12:00-13:00' AS label UNION SELECT 13 AS `hour`,'13:00-14:00' AS label UNION SELECT 14 AS `hour`,'14:00-15:00' AS label UNION SELECT 15 AS `hour`,'15:00-16:00' AS label UNION SELECT 16 AS `hour`,'16:00-17:00' AS label UNION SELECT 17 AS `hour`,'17:00-18:00' AS label UNION SELECT 18 AS `hour`,'18:00-19:00' AS label UNION SELECT 19 AS `hour`,'19:00-20:00' AS label UNION SELECT 20 AS `hour`,'20:00-21:00' AS label UNION SELECT 21 AS `hour`,'21:00-22:00' AS label UNION SELECT 22 AS `hour`,'22:00-23:00' AS label UNION SELECT 23 AS `hour`,'23:00-24:00' AS label) t1 LEFT JOIN (SELECT HOUR(inspection_time) as hour,IFNULL(SUM(IF(dataTable.feedback_end ='1' OR dataTable.feedback_end ='2',1,0)),0) as inspectionTaskBackNum FROM bm_inspection_task dataTable
and dataTable.delete_flag = 0 and dataTable.send_flag = 1 AND dataTable.task_status = '1' ${dataScope}
AND dataTable.grid_id LIKE concat('%',#{gridId},'%')
AND dataTable.inspection_time >= #{queryStartTime} AND dataTable.inspection_time <= #{queryEndTime}
AND FIND_IN_SET(#{keeperId},dataTable.keeper_id) AND dataTable.feedback_keeper_id = #{keeperId}
GROUP BY HOUR(dataTable.inspection_time) )t2 ON t1.hour = t2.hour ORDER BY t1.`hour`

SELECT cc.assigned_date AS assignedDate,IFNULL(SUM(t.inspectionTaskNum),0) AS inspectionTaskNum, IFNULL(SUM(t.taskCompletedNum),0) AS taskCompletedNum,IFNULL(SUM(t.taskIncompleteNum),0) AS taskIncompleteNum FROM( (SELECT date_format(assigned_date,'%Y-%m-%d') assigned_date FROM (SELECT adddate('2019-01-01',t3.i*1000 + t2.i*100 + t1.i*10 + t0.i) assigned_date FROM (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t0, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t1, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t2, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t3 ) c
and assigned_date between SUBSTR(#{queryStartTime},1,10) and SUBSTR(#{queryEndTime},1,10)
) cc LEFT JOIN (SELECT date_format( dataTable.create_time, '%Y-%m-%d' ) as create_time,IFNULL( SUM( IF ( (dataTable.task_status = '1') OR dataTable.task_status = '2' , 1, 0 )), 0 ) as inspectionTaskNum,IFNULL(SUM(IF(dataTable.task_status ='1' ,1,0)),0) as taskCompletedNum, IFNULL(SUM(IF(dataTable.task_status ='2',1,0)),0) as taskIncompleteNum FROM bm_inspection_task dataTable
and dataTable.delete_flag = 0 and dataTable.send_flag = 1 ${dataScope}
AND dataTable.grid_id LIKE concat('%',#{gridId},'%')
AND dataTable.create_time >= #{queryStartTime} AND dataTable.create_time <= #{queryEndTime}
GROUP BY date_format( dataTable.create_time, '%Y-%m-%d' ))t ON date_format(t.create_time,'%Y-%m-%d') = cc.assigned_date) GROUP BY cc.assigned_date ORDER BY date_format(cc.assigned_date,'%Y-%m-%d')

SELECT cc.assigned_date AS assignedDate,IFNULL(SUM(t.inspectionTaskNum),0) AS inspectionTaskNum, IFNULL(SUM(t.taskCompletedNum),0) AS taskCompletedNum,IFNULL(SUM(t.taskIncompleteNum),0) AS taskIncompleteNum FROM( (SELECT date_format(assigned_date,'%Y-%m-%d') assigned_date FROM (SELECT adddate('2019-01-01',t3.i*1000 + t2.i*100 + t1.i*10 + t0.i) assigned_date FROM (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t0, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t1, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t2, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t3 ) c
and assigned_date between SUBSTR(#{queryStartTime},1,10) and SUBSTR(#{queryEndTime},1,10)
) cc LEFT JOIN (SELECT date_format( dataTable.create_time, '%Y-%m-%d' ) as create_time,IFNULL( SUM( IF ( (dataTable.task_status = '1' and dataTable.feedback_keeper_id = #{keeperId}) OR dataTable.task_status = '2' , 1, 0 )), 0 ) as inspectionTaskNum,IFNULL(SUM(IF(dataTable.task_status ='1' and dataTable.feedback_keeper_id = #{keeperId} ,1,0)),0) as taskCompletedNum, IFNULL(SUM(IF(dataTable.task_status ='2',1,0)),0) as taskIncompleteNum FROM bm_inspection_task dataTable
and dataTable.delete_flag = 0 and dataTable.send_flag = 1 ${dataScope}
AND dataTable.grid_id LIKE concat('%',#{gridId},'%')
AND dataTable.create_time >= #{queryStartTime} AND dataTable.create_time <= #{queryEndTime}
AND FIND_IN_SET(#{keeperId},dataTable.keeper_id)
GROUP BY date_format( dataTable.create_time, '%Y-%m-%d' ))t ON date_format(t.create_time,'%Y-%m-%d') = cc.assigned_date) GROUP BY cc.assigned_date ORDER BY date_format(cc.assigned_date,'%Y-%m-%d')

SELECT CAST(a.keeperId AS CHAR) as keeperId,a.keeperName,a.inspectionTaskNum,a.taskCompletedNum,a.taskIncompleteNum, IF(a.inspectionTaskNum = 0,NULL,IFNULL(ROUND((IFNULL(a.taskCompletedNum,0)/a.inspectionTaskNum) *100),0)) AS completedRate, IFNULL((IFNULL(a.taskCompletedNum,0)/a.inspectionTaskNum) *100,0) AS completedRates FROM( SELECT r.keeper_id AS keeperId, r.keeper_name AS keeperName, IFNULL( SUM( IF ( (dataTable.task_status = '1' and dataTable.feedback_keeper_id =r.keeper_id) OR dataTable.task_status = '2' , 1, 0 )), 0 ) AS inspectionTaskNum, IFNULL( SUM( IF ( dataTable.task_status = '1' and dataTable.feedback_keeper_id =r.keeper_id , 1, 0 )), 0 ) AS taskCompletedNum, IFNULL( SUM( IF ( dataTable.task_status = '2', 1, 0 )), 0 ) AS taskIncompleteNum FROM bm_inspection_task dataTable LEFT JOIN bm_gridkeeper r ON FIND_IN_SET(r.keeper_id,dataTable.keeper_id) and r.delete_flag = 0
LEFT JOIN bm_grid t ON dataTable.grid_id = t.grid_id and t.delete_flag = 0
and dataTable.send_flag = 1 and dataTable.delete_flag = 0
AND dataTable.create_time >= #{queryStartTime} AND dataTable.create_time <= #{queryEndTime}
AND dataTable.grid_id = #{gridId}
${dataScope}
GROUP BY r.keeper_id )a WHERE a.inspectionTaskNum >0
AND a.keeperId = #{keeperId}
ORDER BY inspectionTaskNum DESC, ISNULL( completedRate ),completedRates DESC,CONVERT(a.keeperName USING GBK)

SELECT CAST(a.keeperId AS CHAR) as keeperId,a.keeperName,a.inspectionTaskNum,a.taskCompletedNum,a.taskIncompleteNum, IF(a.inspectionTaskNum = 0,NULL,IFNULL(ROUND((IFNULL(a.taskCompletedNum,0)/a.inspectionTaskNum) *100),0)) AS completedRate, IFNULL((IFNULL(a.taskCompletedNum,0)/a.inspectionTaskNum) *100,0) AS completedRates FROM( SELECT r.keeper_id AS keeperId, r.keeper_name AS keeperName, IFNULL( SUM( IF ( (dataTable.task_status = '1' and dataTable.feedback_keeper_id =r.keeper_id) OR dataTable.task_status = '2' , 1, 0 )), 0 ) AS inspectionTaskNum, IFNULL( SUM( IF ( dataTable.task_status = '1' and dataTable.feedback_keeper_id =r.keeper_id , 1, 0 )), 0 ) AS taskCompletedNum, IFNULL( SUM( IF ( dataTable.task_status = '2', 1, 0 )), 0 ) AS taskIncompleteNum FROM bm_inspection_task dataTable LEFT JOIN bm_gridkeeper r ON FIND_IN_SET(r.keeper_id,dataTable.keeper_id) and r.delete_flag = 0
LEFT JOIN bm_grid t ON dataTable.grid_id = t.grid_id and t.delete_flag = 0
and dataTable.send_flag = 1 and dataTable.delete_flag = 0
AND dataTable.create_time >= #{queryStartTime} AND dataTable.create_time <= #{queryEndTime}
AND dataTable.grid_id = #{gridId}
${dataScope}
GROUP BY r.keeper_id )a WHERE a.inspectionTaskNum >0
AND a.keeperId = #{keeperId}
ORDER BY ISNULL( completedRate ), completedRates DESC, CONVERT ( a.keeperName USING GBK )

SELECT
    count( conf_id ) AS allNum
FROM
    bm_inspection_conf
WHERE delete_flag = 0 ${dataScope}

    and DATE_FORMAT(create_time,'%Y-%m-%d') >= #{createStartDate}


    and DATE_FORMAT(create_time,'%Y-%m-%d') <= #{createEndDate}
